// ---- git branch picker ---------------------------------------------------------------------------

/// Commit `rel` (created with `content`) so the repo has a resolvable HEAD.
/// Commit the working-tree state of `rel` under a chosen message — for tests that care about
/// subjects (the log picker's rows) rather than content.
fn commit_with_message(repo: &git2::Repository, rel: &str, message: &str) {
    let mut index = repo.index().unwrap();
    index.add_path(std::path::Path::new(rel)).unwrap();
    index.write().unwrap();
    let tree = repo.find_tree(index.write_tree().unwrap()).unwrap();
    let sig = git2::Signature::now("Test", "test@example.com").unwrap();
    let parents = match repo.head().ok().and_then(|h| h.peel_to_commit().ok()) {
        Some(c) => vec![c],
        None => vec![],
    };
    repo.commit(
        Some("HEAD"),
        &sig,
        &sig,
        message,
        &tree,
        &parents.iter().collect::<Vec<_>>(),
    )
    .unwrap();
}

// -------- the branch picker (PickerKind::GitBranches) ---------------------------------------------

/// The branch rows of a `picker/view` on `GitBranches`, in window order.
fn branch_rows(items: &[PickerItem]) -> Vec<(String, bool, Option<String>)> {
    items
        .iter()
        .map(|it| match it {
            PickerItem::GitBranch {
                name,
                is_head,
                checkout,
                ..
            } => (
                name.clone(),
                *is_head,
                checkout.as_ref().map(|k| k.path.clone()),
            ),
            other => panic!("expected a branch row, got {other:?}"),
        })
        .collect()
}

#[tokio::test]
async fn branch_picker_lists_local_branches_with_head_first() {
    let dir = tempfile::tempdir().unwrap();
    let root = dir.path().canonicalize().unwrap();
    let repo = init_repo_at(&root);
    commit_file(&repo, "a.rs", "one\n");
    let head = repo.head().unwrap().peel_to_commit().unwrap();
    repo.branch("feature", &head, false).unwrap();

    let (server, mut ws, buffer) = setup_repos_workspace_on(vec![root.clone()], "a.rs").await;
    let view =
        send_request::<PickerView>(&mut ws, &view_params_on(PickerKind::GitBranches, buffer)).await;
    let update = view.update.expect("the view carries its initial window");

    assert_eq!(update.kind, PickerKind::GitBranches);
    assert_eq!(update.total_matches, 2);
    assert_eq!(
        branch_rows(update.items()),
        vec![
            // The branch you are on carries the checkout holding it, like any other. The row for
            // where you are is a worktree row too — that is what lets "already here" and "another
            // tree has it" be different sentences rather than one refusal.
            (
                "main".to_string(),
                true,
                Some(root.to_string_lossy().into_owned())
            ),
            ("feature".to_string(), false, None),
        ],
        "the checked-out branch sorts first; `feature` is held by no tree"
    );
    // Every row names the repo it belongs to, so the checkout the client fires can't re-resolve
    // to a different one if the active buffer moves while the picker is up.
    let PickerItem::GitBranch {
        repo_id, subject, ..
    } = &update.items()[0]
    else {
        panic!("branch row");
    };
    assert_eq!(*repo_id, root.to_string_lossy());
    assert_eq!(subject, "init", "the tip commit's summary rides the row");
    drop(server);
}

/// "Which branch am I on" is the *selection*, like every other picker — not a `●` in a leading
/// column. The server resolves the HEAD row on a fresh open and echoes it as `effective_center_on`;
/// the client adopts it as its highlight (`current_branch_item`).
#[tokio::test]
async fn the_branch_you_are_on_is_the_initial_selection() {
    let dir = tempfile::tempdir().unwrap();
    let root = dir.path().canonicalize().unwrap();
    let repo = init_repo_at(&root);
    commit_file(&repo, "a.rs", "one\n");
    let head = repo.head().unwrap().peel_to_commit().unwrap();
    repo.branch("feature", &head, false).unwrap();

    let (server, mut ws, buffer) = setup_repos_workspace_on(vec![root.clone()], "a.rs").await;
    let view =
        send_request::<PickerView>(&mut ws, &view_params_on(PickerKind::GitBranches, buffer)).await;
    let centred = view
        .effective_center_on
        .expect("a fresh open centres on the branch HEAD is on");
    assert!(
        matches!(&centred, PickerItem::GitBranch { name, is_head, .. }
            if name == "main" && *is_head),
        "centred on the current branch: {centred:?}"
    );

    // A re-view must not yank the highlight back — the user may have moved it.
    let again = send_request::<PickerView>(
        &mut ws,
        &PickerViewParams {
            view_id: None,
            reset: PickerReset::Keep,
            ..view_params_on(PickerKind::GitBranches, buffer)
        },
    )
    .await;
    assert!(again.effective_center_on.is_none());

    drop(server);
}

