/// Pull announces itself as its own kind, not as the fetch it contains. The status bar reads the
/// label off this, so a pull that reported `Fetch` would spend the whole transfer lying about what
/// it was doing — and `Space g x` would be cancelling something the user wasn't told about.
#[tokio::test]
async fn git_pull_announces_itself_as_a_pull() {
    let (_dir, _base, ours, _url) = repo_with_origin();
    run_git(&ours, &["push", "-u", "origin", "main"]);
    let (server, mut ws) = setup_repos_workspace(vec![ours.clone()]).await;

    // By hand, because `send_request` drains the notifications this test is about.
    let req = Request {
        jsonrpc: JsonRpc,
        id: 2,
        method: GitPull::NAME.into(),
        params: Some(
            serde_json::to_value(GitPullParams {
                repo_id: Some(ours.to_string_lossy().into()),
                buffer_id: None,
            })
            .unwrap(),
        ),
    };
    ws.send(Message::text(serde_json::to_string(&req).unwrap()))
        .await
        .unwrap();

    let started = expect_notification::<GitOperationChanged>(&mut ws).await;
    let op = started.operation.expect("an operation is in flight");
    assert_eq!(op.kind, GitOperationKind::Pull);

    let finished = expect_notification::<GitOperationChanged>(&mut ws).await;
    assert!(
        finished.operation.is_none(),
        "the indicator has to clear, got {:?}",
        finished.operation
    );

    drop(server);
}

// -------- stopped operations (mid-merge / mid-rebase) ------------------------------------------------

/// Leave `ours` stopped in the middle of a conflicting rebase, the state a `pull --rebase` that hit
/// a conflict leaves behind. Returns the buffer on the conflicted file.
async fn setup_stopped_rebase() -> (
    aether_server::ServerHandle,
    Ws,
    tempfile::TempDir,
    std::path::PathBuf, // ours
    u64,                // buffer id for a.rs
) {
    let (server, mut ws, dir, base, ours, url, buffer_id) = setup_pull_workspace(true).await;
    someone_else_pushes(&base, &url, "a.rs");
    std::fs::write(ours.join("a.rs"), "mine\n").unwrap();
    run_git(&ours, &["add", "a.rs"]);
    run_git(&ours, &["commit", "-m", "my edit"]);

    let res = pull(&mut ws, &ours).await;
    assert_eq!(res.status, GitPullStatus::Conflicted, "{}", res.message);
    assert_eq!(
        res.operation,
        Some(GitRepoOperation::Rebase),
        "the result names which operation stopped, so the client can say `--continue` vs `commit`"
    );
    (server, ws, dir, ours, buffer_id)
}

/// A stopped rebase **detaches HEAD**, so the pre-flight order is what decides whether the user is
/// told the cause or the symptom. Checking detached-HEAD first would answer "not on a branch" to
/// someone who is mid-rebase from a pull that conflicted a minute ago — true, and useless.
#[tokio::test]
async fn a_pull_mid_rebase_names_the_operation_not_the_detached_head() {
    let (server, mut ws, _dir, ours, _buffer_id) = setup_stopped_rebase().await;

    let res = pull(&mut ws, &ours).await;
    assert_eq!(res.status, GitPullStatus::OperationInProgress);
    assert_eq!(res.operation, Some(GitRepoOperation::Rebase));
    assert_eq!(
        res.conflicts,
        vec!["a.rs".to_string()],
        "the conflicts still needing resolution ride along — that's the actionable part"
    );

    drop(server);
}

/// The status bar's copy of the same fact. Without it the window silently swaps the branch name for
/// a detached-HEAD hash and drops the ahead/behind arrows, and nothing on screen ever says "rebase"
/// once the toast has faded.
#[tokio::test]
async fn buffer_status_reports_a_stopped_rebase() {
    let (server, mut ws, _dir, _ours, _buffer_id) = setup_stopped_rebase().await;

    let gs = git_status_of(&mut ws, "a.rs").await;
    assert_eq!(gs.operation, Some(GitRepoOperation::Rebase));
    // The degradation this exists to explain, asserted so the pairing is visible: detached HEAD, so
    // the branch label is a bare hash and there is no upstream to compare against.
    assert!(
        gs.upstream.is_none(),
        "detached mid-rebase — nothing to be ahead of, got {:?}",
        gs.upstream
    );

    drop(server);
}

/// Staging a hunk in a conflicted file is refused rather than quietly meaning something else.
///
/// A conflicted path has no stage-0 index entry, so writing one is `git add`'s "mark resolved" —
/// the user would press *stage this hunk* and get *resolve this file*, markers and all. The index
/// still holding its conflict stages afterwards is the real assertion: the status alone would pass
/// even if the write had happened.
#[tokio::test]
async fn staging_a_hunk_in_a_conflicted_file_is_refused() {
    let (server, mut ws, _dir, ours, buffer_id) = setup_stopped_rebase().await;

    let res = apply_hunk(&mut ws, buffer_id, HunkAction::Stage).await;
    assert_eq!(res.status, ApplyHunkStatus::Conflicted);

    let repo = git2::Repository::open(&ours).unwrap();
    assert!(
        repo.index().unwrap().has_conflicts(),
        "the conflict must survive — a stage-0 write would have marked it resolved"
    );

    drop(server);
}

/// Unstaging inside a conflicted file is refused at *both* scopes, where staging the whole file
/// is the one thing that does mean something there ("mark resolved").
///
/// There is no stage-0 entry to pull out of, so an unstage has nothing to act on — and the
/// gesture that puts a conflict back is `Space g d`, not a key that says "unstage". As with the
/// staging refusal, the surviving conflict stages are the real assertion.
#[tokio::test]
async fn unstaging_a_conflicted_file_is_refused_at_both_scopes() {
    let (server, mut ws, _dir, ours, buffer_id) = setup_stopped_rebase().await;

    for (_, scope) in [(4, ApplyScope::Cursor), (5, ApplyScope::File)] {
        let res = apply_hunk_scoped(&mut ws, buffer_id, HunkAction::Unstage, scope).await;
        assert_eq!(
            res.status,
            ApplyHunkStatus::Conflicted,
            "unstage must be refused at {scope:?}"
        );
    }

    let repo = git2::Repository::open(&ours).unwrap();
    assert!(
        repo.index().unwrap().has_conflicts(),
        "the conflict must survive an unstage that was refused"
    );

    drop(server);
}

/// The property the direction split exists for: a key that says "stage" only ever stages. Pressed
/// again on a region it has already staged it reports there is nothing to do — where the old
/// toggle would silently have unstaged it, undoing the press before it.
#[tokio::test]
async fn staging_twice_stages_once_and_then_says_there_is_nothing_to_do() {
    let dir = tempfile::tempdir().unwrap();
    git_commit_file(dir.path(), "edit.rs", "alpha\nbeta\ngamma\n");
    std::fs::write(dir.path().join("edit.rs"), "alpha\nBETA\ngamma\n").unwrap();
    let (server, mut ws, buffer_id) = setup_git_apply(dir.path(), "twice-proj", "edit.rs").await;

    set_cursor(&mut ws, buffer_id, 1, 2).await;
    let r = apply_hunk(&mut ws, buffer_id, HunkAction::Stage).await;
    assert_eq!(r.status, ApplyHunkStatus::Staged);
    let staged = index_text(dir.path(), "edit.rs").unwrap();
    assert_eq!(staged, "alpha\nBETA\ngamma\n");

    let r = apply_hunk(&mut ws, buffer_id, HunkAction::Stage).await;
    assert_eq!(
        r.status,
        ApplyHunkStatus::NoChange,
        "a second stage has nothing to stage"
    );
    assert_eq!(
        index_text(dir.path(), "edit.rs").unwrap(),
        staged,
        "and above all it must not have unstaged what the first press staged"
    );

    // The mirror: unstaging twice takes it out once and then says the same thing.
    let r = apply_hunk(&mut ws, buffer_id, HunkAction::Unstage).await;
    assert_eq!(r.status, ApplyHunkStatus::Unstaged);
    let r = apply_hunk(&mut ws, buffer_id, HunkAction::Unstage).await;
    assert_eq!(r.status, ApplyHunkStatus::NoChange);
    assert_eq!(
        index_text(dir.path(), "edit.rs").unwrap(),
        "alpha\nbeta\ngamma\n",
        "the repeat left the index at HEAD rather than re-staging"
    );

    drop(server);
}

/// Leave `ours` stopped in a merge whose one file is conflicted in **two** separate places — the
/// fixture the navigation and multi-region resolution tests need. Returns the buffer on `a.rs`.
async fn setup_two_block_conflict() -> (
    aether_server::ServerHandle,
    Ws,
    tempfile::TempDir,
    std::path::PathBuf, // ours
    u64,                // buffer id for a.rs
) {
    let (server, mut ws, dir, base, ours, url, buffer_id) = setup_pull_workspace(false).await;
    // A shared base with room between the two edits, pushed so both sides start from it.
    let shared = "top\nb\nc\nd\ne\nf\ng\nh\nbottom\n";
    std::fs::write(ours.join("a.rs"), shared).unwrap();
    run_git(&ours, &["commit", "-am", "shared base"]);
    run_git(&ours, &["push", "origin", "main"]);

    // Their side rewrites the first and last lines...
    let theirs = base.join("theirs");
    run_git(&base, &["clone", &url, "theirs"]);
    std::fs::write(
        theirs.join("a.rs"),
        "their top\nb\nc\nd\ne\nf\ng\nh\ntheir bottom\n",
    )
    .unwrap();
    run_git(&theirs, &["commit", "-am", "their work"]);
    run_git(&theirs, &["push", "origin", "main"]);

    // ...and so do we, differently. Two conflicts, with clean context between them.
    std::fs::write(
        ours.join("a.rs"),
        "my top\nb\nc\nd\ne\nf\ng\nh\nmy bottom\n",
    )
    .unwrap();
    run_git(&ours, &["commit", "-am", "my work"]);

    let res = pull(&mut ws, &ours).await;
    assert_eq!(res.status, GitPullStatus::Conflicted, "{}", res.message);
    (server, ws, dir, ours, buffer_id)
}

/// The conflict markers reach the viewport as per-line sides, so the shells can tell ours from
/// theirs without re-parsing the text — and the *diff* decoration is gone from the same lines.
///
/// The second half is the regression that matters. A conflicted path has no stage-0 index entry, so
/// before this the staged diff was `HEAD → ""` and every line of the file carried a `Deleted`
/// marker: a wall of gutter bars claiming the whole file was staged for deletion.
#[tokio::test]
async fn a_conflicted_buffer_renders_sides_and_no_diff() {
    let (server, mut ws, _dir, _ours, buffer_id) = setup_stopped_rebase().await;

    let window = window_of(&mut ws, buffer_id).await;
    let sides: Vec<Option<ConflictLine>> = window
        .root
        .lines()
        .into_iter()
        .map(|l| l.change.conflict())
        .collect();
    // `<<<<<<< HEAD` / theirs / `=======` / ours / `>>>>>>> commit` — the rebase replays our commit
    // on top of theirs, so "ours" is the upstream side and the labels are what say so.
    assert_eq!(
        sides,
        vec![
            Some(ConflictLine::Marker),
            Some(ConflictLine::Ours),
            Some(ConflictLine::Marker),
            Some(ConflictLine::Theirs),
            Some(ConflictLine::Marker),
            None, // trailing empty line
        ],
        "got {:?}",
        window
            .root
            .lines()
            .into_iter()
            .map(|l| (
                l.change.conflict(),
                l.visual_rows[0].segments[0].text.clone()
            ))
            .collect::<Vec<_>>()
    );
    assert!(
        window
            .root
            .lines()
            .into_iter()
            .all(|l| l.change.marker().is_none()),
        "a conflicted file has no baseline to diff, so no line may claim a diff marker"
    );

    let status = window.git_status.expect("in a repo");
    assert_eq!(status.conflicts, 1, "one block, for the status bar to name");
    assert_eq!(status.operation, Some(GitRepoOperation::Rebase));
    assert!(
        status.staged.is_empty() && status.unstaged.is_empty(),
        "and no change counts: got staged {:?} unstaged {:?}",
        status.staged,
        status.unstaged
    );

    drop(server);
}

/// `c` / `Alt-c` retarget to conflict blocks in a conflicted file. There are no hunks to step
/// between there (nothing to diff against), so without this the motion is dead exactly where the
/// user most needs "take me to the next thing to deal with".
#[tokio::test]
async fn hunk_navigation_steps_conflict_blocks() {
    let (server, mut ws, _dir, _ours, buffer_id) = setup_two_block_conflict().await;

    // The first block starts at line 0 — where the cursor already is — and `Next` moves strictly
    // forward, so one press lands on the *second* block.
    let second = navigate_change_from(
        &mut ws,
        buffer_id,
        0,
        aether_protocol::viewport::FocusStep::Next,
        1,
    )
    .await;
    assert!(
        second.moved && second.cursor.position.line > 0,
        "{second:?}"
    );
    // Nothing past the last block...
    let past = navigate_change_from(
        &mut ws,
        buffer_id,
        second.cursor.position.line,
        aether_protocol::viewport::FocusStep::Next,
        1,
    )
    .await;
    assert!(!past.moved);
    // ...and stepping back reaches the first, then stops.
    let first = navigate_change_from(
        &mut ws,
        buffer_id,
        second.cursor.position.line,
        aether_protocol::viewport::FocusStep::Previous,
        1,
    )
    .await;
    assert_eq!(first.cursor.position.line, 0, "{first:?}");
    let before = navigate_change_from(
        &mut ws,
        buffer_id,
        0,
        aether_protocol::viewport::FocusStep::Previous,
        1,
    )
    .await;
    assert!(!before.moved);

    // Each landing is a `<<<<<<<` line: the top of a block, not somewhere inside one.
    let window = window_of(&mut ws, buffer_id).await;
    for line in [first.cursor.position.line, second.cursor.position.line] {
        assert_eq!(
            window.root.lines()[line as usize].change.conflict(),
            Some(ConflictLine::Marker),
            "landed mid-block at line {line}"
        );
    }

    drop(server);
}

/// [`apply_hunk`] with the scope spelled out — `ApplyScope::File` is "mark resolved" on a
/// conflicted path.
async fn apply_hunk_scoped(
    ws: &mut Ws,
    buffer_id: u64,
    action: HunkAction,
    scope: ApplyScope,
) -> GitApplyHunkResult {
    send_request::<GitApplyHunk>(
        ws,
        &GitApplyHunkParams {
            buffer_id,
            action,
            scope,
        },
    )
    .await
}

/// Taking a side rewrites the buffer, and is **one undo step** — which is what makes trying a side
/// and changing your mind cost a single `Ctrl-z` rather than unpicking a multi-line edit.
#[tokio::test]
async fn taking_a_side_resolves_the_block_and_undoes_in_one_step() {
    let (server, mut ws, _dir, ours, buffer_id) = setup_stopped_rebase().await;
    let before = buffer_text(&mut ws, buffer_id).await;

    // The cursor sits at the top of the file, inside the only block.
    let res = resolve_conflict(&mut ws, buffer_id, ConflictSide::Theirs).await;
    assert_eq!(res.status, ResolveConflictStatus::Resolved);
    assert_eq!((res.resolved, res.remaining), (1, 0));

    let after = buffer_text(&mut ws, buffer_id).await;
    assert!(
        !after.contains("<<<<<<<") && !after.contains("=======") && !after.contains(">>>>>>>"),
        "markers must go with the resolution, got {after:?}"
    );
    assert_eq!(
        after, "mine\n",
        "theirs, mid-rebase, is the commit being replayed"
    );
    // Still conflicted as far as git is concerned: resolving is editing, and nothing has been
    // marked resolved (or even saved) yet.
    assert!(git2::Repository::open(&ours)
        .unwrap()
        .index()
        .unwrap()
        .has_conflicts());

    let undo: UndoResult = send_request::<EditUndo>(
        &mut ws,
        &UndoRedoParams {
            buffer_id,
            count: 1,
            collapse_selection: false,
        },
    )
    .await;
    assert!(undo.applied);
    assert_eq!(
        buffer_text(&mut ws, buffer_id).await,
        before,
        "one undo restores the whole block"
    );

    drop(server);
}

/// A selection spanning several blocks resolves them all — the addressing `git/apply_hunk` uses,
/// and the reason there is no separate "take all of theirs in this file" key.
#[tokio::test]
async fn a_selection_resolves_every_block_it_covers() {
    let (server, mut ws, _dir, _ours, buffer_id) = setup_two_block_conflict().await;

    let _: CursorState =
        send_request::<CursorSelectAll>(&mut ws, &CursorSelectAllParams { buffer_id }).await;
    let res = resolve_conflict(&mut ws, buffer_id, ConflictSide::Ours).await;
    assert_eq!((res.resolved, res.remaining), (2, 0), "{res:?}");

    let text = buffer_text(&mut ws, buffer_id).await;
    // Mid-*merge*, "ours" is the local branch — the opposite of what it means mid-rebase, where the
    // replayed commit is "theirs" (see `taking_a_side_resolves_the_block_and_undoes_in_one_step`).
    // Nothing here has to know that: the markers' own labels are what the user reads.
    assert_eq!(
        text, "my top\nb\nc\nd\ne\nf\ng\nh\nmy bottom\n",
        "ours is the local side mid-merge"
    );
    // And the decoration is gone with them.
    let window = window_of(&mut ws, buffer_id).await;
    assert!(window
        .root
        .lines()
        .into_iter()
        .all(|l| l.change.conflict().is_none()));

    drop(server);
}

/// Taking both sides keeps them in file order, and only the block the cursor is in.
#[tokio::test]
async fn taking_both_keeps_both_sides_of_only_the_cursors_block() {
    let (server, mut ws, _dir, _ours, buffer_id) = setup_two_block_conflict().await;

    // Cursor at line 0 — inside the first block, well before the second.
    let res = resolve_conflict(&mut ws, buffer_id, ConflictSide::Both).await;
    assert_eq!((res.resolved, res.remaining), (1, 1), "{res:?}");

    let text = buffer_text(&mut ws, buffer_id).await;
    let head = text.lines().take(2).collect::<Vec<_>>();
    assert_eq!(
        head,
        vec!["my top", "their top"],
        "ours then theirs, in file order"
    );
    assert!(
        text.contains("<<<<<<<"),
        "the block the cursor wasn't in keeps its markers: {text:?}"
    );

    drop(server);
}

/// With the cursor outside every block, the verbs say so rather than guessing at the nearest one —
/// resolving the wrong conflict is not something a toast can undo.
#[tokio::test]
async fn taking_a_side_outside_a_block_resolves_nothing() {
    let (server, mut ws, _dir, _ours, buffer_id) = setup_two_block_conflict().await;

    // Line 5 is clean context between the two blocks.
    let target = LogicalPosition { line: 5, col: 0 };
    let _: CursorState = send_request::<CursorSet>(
        &mut ws,
        &CursorSetParams {
            granularity: Granularity::Char,
            buffer_id,
            position: target,
            anchor: target,
        },
    )
    .await;
    let res = resolve_conflict(&mut ws, buffer_id, ConflictSide::Ours).await;
    assert_eq!(res.status, ResolveConflictStatus::NoConflict);
    assert_eq!(res.resolved, 0);
    assert_eq!(res.remaining, 2, "both blocks still there");

    drop(server);
}

/// The whole path from "git stopped here" to "the index agrees with me", and the two gates on the
/// way: markers still present, and edits not yet on disk. `git add` writes what is on *disk*, so
/// both refusals are about the file the index would actually get.
#[tokio::test]
async fn marking_resolved_gates_on_markers_then_on_saving() {
    let (server, mut ws, _dir, ours, buffer_id) = setup_stopped_rebase().await;
    // Markers still in the file: refused. This is the one that stops a broken merge being committed.
    let res = apply_hunk_scoped(&mut ws, buffer_id, HunkAction::Stage, ApplyScope::File).await;
    assert_eq!(res.status, ApplyHunkStatus::MarkersRemain);

    // Resolved in the buffer but not saved: still refused, because git would stage the old bytes.
    let _ = resolve_conflict(&mut ws, buffer_id, ConflictSide::Ours).await;
    let res = apply_hunk_scoped(&mut ws, buffer_id, HunkAction::Stage, ApplyScope::File).await;
    assert_eq!(res.status, ApplyHunkStatus::DirtyBuffer);

    let _: BufferSaveResult = send_request::<BufferSave>(
        &mut ws,
        &BufferSaveParams {
            buffer_id,
            path_index: None,
            relative_path: None,
            overwrite: false,
        },
    )
    .await;
    let res = apply_hunk_scoped(&mut ws, buffer_id, HunkAction::Stage, ApplyScope::File).await;
    assert_eq!(res.status, ApplyHunkStatus::Resolved);

    // The real assertion: git no longer considers the file conflicted, so the operation can be
    // concluded. A status alone would pass even if nothing had been written.
    let repo = git2::Repository::open(&ours).unwrap();
    assert!(
        !repo.index().unwrap().has_conflicts(),
        "the conflict stages must be gone — that is what `git add` does here"
    );
    // And the editor stops describing a conflict that has ended.
    let window = window_of(&mut ws, buffer_id).await;
    assert_eq!(window.git_status.expect("in a repo").conflicts, 0);
    assert!(window
        .root
        .lines()
        .into_iter()
        .all(|l| l.change.conflict().is_none()));

    drop(server);
}

/// Reverting inside a conflicted file is refused too. There is no baseline to revert to mid-merge,
/// so "put this back" would mean silently discarding one side — which is what the conflict verbs
/// are for, deliberately and by name.
#[tokio::test]
async fn reverting_in_a_conflicted_file_is_refused() {
    let (server, mut ws, _dir, ours, buffer_id) = setup_stopped_rebase().await;
    let before = buffer_text(&mut ws, buffer_id).await;

    for (_, scope) in [(5, ApplyScope::Cursor), (6, ApplyScope::File)] {
        let res = apply_hunk_scoped(&mut ws, buffer_id, HunkAction::Revert, scope).await;
        assert_eq!(res.status, ApplyHunkStatus::Conflicted, "scope {scope:?}");
    }
    assert_eq!(
        buffer_text(&mut ws, buffer_id).await,
        before,
        "and nothing was touched"
    );
    assert!(git2::Repository::open(&ours)
        .unwrap()
        .index()
        .unwrap()
        .has_conflicts());

    drop(server);
}

/// Resolve, mark resolved, then `Space g c`: the message comes pre-filled from the *rebase's* own
/// commit message, and the commit runs `rebase --continue` behind it. Without the continuation the
/// user is left committed but still mid-rebase on a detached HEAD, with no in-editor way on.
#[tokio::test]
async fn committing_mid_rebase_uses_its_message_and_continues_the_rebase() {
    let (server, mut ws, _dir, ours, buffer_id) = setup_stopped_rebase().await;

    // Resolve, save, mark resolved — the three steps before the commit.
    let _ = resolve_conflict(&mut ws, buffer_id, ConflictSide::Theirs).await;
    let _: BufferSaveResult = send_request::<BufferSave>(
        &mut ws,
        &BufferSaveParams {
            buffer_id,
            path_index: None,
            relative_path: None,
            overwrite: false,
        },
    )
    .await;
    let res = apply_hunk_scoped(&mut ws, buffer_id, HunkAction::Stage, ApplyScope::File).await;
    assert_eq!(res.status, ApplyHunkStatus::Resolved);

    // The template is seeded from the rebase's stored message, not blank: this is the commit being
    // replayed, and its message is the one being reused.
    let prepared = prepare_commit(&mut ws, &ours, false).await;
    assert!(
        prepared.blocked_by_conflicts.is_empty(),
        "nothing conflicted now: {:?}",
        prepared.blocked_by_conflicts
    );
    let template = std::fs::read_to_string(&prepared.path).unwrap();
    assert!(
        template.starts_with("my edit"),
        "expected the replayed commit's message, got {template:?}"
    );

    let res = commit(&mut ws, &ours, false).await;
    assert!(res.commit.is_some(), "{}", res.message);
    assert_eq!(
        res.operation,
        Some(GitRepoOperation::Rebase),
        "the commit concluded the rebase, and says so"
    );
    assert!(
        res.conflicts.is_empty(),
        "nothing left: {:?}",
        res.conflicts
    );

    // The real assertion: the rebase is over and HEAD is back on the branch.
    let repo = git2::Repository::open(&ours).unwrap();
    assert_eq!(repo.state(), git2::RepositoryState::Clean);
    assert!(!repo.head_detached().unwrap(), "back on a branch");

    drop(server);
}

/// Mid-*merge* the same key finishes the merge, and the template is git's own `MERGE_MSG` — without
/// which `Space g c` would replace git's merge message with a blank one.
#[tokio::test]
async fn committing_mid_merge_uses_merge_msg_and_ends_the_merge() {
    let (server, mut ws, _dir, ours, buffer_id) = setup_two_block_conflict().await;

    let _: CursorState =
        send_request::<CursorSelectAll>(&mut ws, &CursorSelectAllParams { buffer_id }).await;
    let _ = resolve_conflict(&mut ws, buffer_id, ConflictSide::Ours).await;
    let _: BufferSaveResult = send_request::<BufferSave>(
        &mut ws,
        &BufferSaveParams {
            buffer_id,
            path_index: None,
            relative_path: None,
            overwrite: false,
        },
    )
    .await;
    let _ = apply_hunk_scoped(&mut ws, buffer_id, HunkAction::Stage, ApplyScope::File).await;

    let prepared = prepare_commit(&mut ws, &ours, false).await;
    let template = std::fs::read_to_string(&prepared.path).unwrap();
    assert!(
        template.contains("Merge branch"),
        "expected git's own merge message, got {template:?}"
    );

    let res = commit(&mut ws, &ours, false).await;
    let made = res.commit.expect("merge commit created");
    assert!(
        made.message.starts_with("Merge"),
        "git's own merge message, kept: {:?}",
        made.message
    );
    // No `--continue` for a merge: committing *is* the end of it.
    let repo = git2::Repository::open(&ours).unwrap();
    assert_eq!(repo.state(), git2::RepositoryState::Clean);
    assert_eq!(
        repo.head()
            .unwrap()
            .peel_to_commit()
            .unwrap()
            .parent_count(),
        2,
        "a real merge commit"
    );

    drop(server);
}

/// Committing with conflicts still outstanding is refused *before* a message buffer opens. Git's own
/// refusal arrives after the message is written and names the state rather than the files.
#[tokio::test]
async fn preparing_a_commit_refuses_while_files_are_conflicted() {
    let (server, mut ws, _dir, ours, _buffer_id) = setup_stopped_rebase().await;

    let prepared = prepare_commit(&mut ws, &ours, false).await;
    assert_eq!(prepared.blocked_by_conflicts, vec!["a.rs".to_string()]);
    assert!(
        prepared.path.is_empty(),
        "nothing prepared, so no buffer to open"
    );

    drop(server);
}

/// The way out: abandoning a stopped rebase puts HEAD back on the branch it detached from, so the
/// editor is never a place you can get stuck.
#[tokio::test]
async fn aborting_a_stopped_rebase_puts_the_branch_back() {
    let (server, mut ws, _dir, ours, _buffer_id) = setup_stopped_rebase().await;
    let repo = git2::Repository::open(&ours).unwrap();
    assert!(repo.head_detached().unwrap(), "mid-rebase, as set up");

    let res: GitAbortOperationResult = send_request::<GitAbortOperation>(
        &mut ws,
        &GitAbortOperationParams {
            repo_id: Some(ours.to_string_lossy().into()),
            buffer_id: None,
        },
    )
    .await;
    assert_eq!(res.status, GitAbortStatus::Aborted);
    assert_eq!(res.operation, Some(GitRepoOperation::Rebase));

    let repo = git2::Repository::open(&ours).unwrap();
    assert_eq!(repo.state(), git2::RepositoryState::Clean);
    assert!(!repo.head_detached().unwrap());
    // The conflicted file is back to our version, and the buffer showing it was reloaded.
    assert_eq!(
        std::fs::read_to_string(ours.join("a.rs")).unwrap(),
        "mine\n"
    );

    // Pressing it again on a clean repo says so rather than failing.
    let res: GitAbortOperationResult = send_request::<GitAbortOperation>(
        &mut ws,
        &GitAbortOperationParams {
            repo_id: Some(ours.to_string_lossy().into()),
            buffer_id: None,
        },
    )
    .await;
    assert_eq!(res.status, GitAbortStatus::NothingInProgress);

    drop(server);
}

/// Resolving one block of two leaves a file that is *half* conflicted, and both halves have to read
/// correctly at once: the block still in dispute shows conflict sides and no diff, and the region
/// just resolved shows as an ordinary change against HEAD — in the gutter and in the changes list.
///
/// The bug this pins: suppressing the diff per *file* meant the resolved half vanished from the
/// gutter while the changes picker fell back to a diff with no index blob and listed the whole file
/// as new. Two surfaces, two different wrong answers.
#[tokio::test]
async fn a_half_resolved_file_shows_conflicts_and_changes_side_by_side() {
    let (server, mut ws, _dir, _ours, buffer_id) = setup_two_block_conflict().await;

    // Cursor starts at line 0, inside the first block.
    let res = resolve_conflict(&mut ws, buffer_id, ConflictSide::Theirs).await;
    assert_eq!((res.resolved, res.remaining), (1, 1));

    let window = window_of(&mut ws, buffer_id).await;
    assert!(
        window
            .root
            .lines()
            .into_iter()
            .any(|l| l.change.conflict().is_some()),
        "the untouched block still reads as a conflict"
    );
    assert!(
        window
            .root
            .lines()
            .into_iter()
            .any(|l| l.change.marker().is_some()),
        "and the resolved region reads as a change: {:?}",
        window
            .root
            .lines()
            .into_iter()
            .map(|l| (l.change.conflict(), l.change.marker()))
            .collect::<Vec<_>>()
    );
    // The rule that lets both encodings coexist — never on the same line — used to be asserted
    // here. It is now unrepresentable: `LineChange` has no variant carrying both.
    let status = window.git_status.expect("in a repo");
    assert_eq!(status.conflicts, 1);
    assert!(
        status.staged.is_empty(),
        "nothing is staged while the index holds conflict stages: {:?}",
        status.staged
    );

    // The changes picker agrees: one conflict row, one change row — not one whole-file row.
    let view = send_request::<PickerView>(
        &mut ws,
        &PickerViewParams {
            view_id: None,
            limit: 30,
            // The file-scoped picker is built from the buffer it names.
            buffer_id: Some(buffer_id),
            ..view_params(PickerKind::GitChangesFile)
        },
    )
    .await;
    let update = view.update.expect("the view carries its initial window");
    assert_eq!(
        update.total_matches,
        2,
        "expected the remaining block plus the resolved change, got {:?}",
        update.items()
    );

    drop(server);
}

/// `Space c` lists a conflicted file as one row per block — which is how you find the conflicts
/// again once the pull's toast has faded.
///
/// The regression underneath: a conflicted path has no index entry, so the ordinary diff collapses
/// into the *whole file* as a single hunk. One row saying "everything changed" is no way to find
/// two conflicts.
#[tokio::test]
async fn git_changes_picker_lists_conflict_blocks() {
    let (server, mut ws, _dir, _ours, _buffer_id) = setup_two_block_conflict().await;

    let view = send_request::<PickerView>(
        &mut ws,
        &PickerViewParams {
            view_id: None,
            limit: 30,
            ..view_params(PickerKind::GitChanges)
        },
    )
    .await;
    let update = view.update.expect("the view carries its initial window");
    assert_eq!(
        update.total_matches,
        2,
        "one row per conflict block, not one whole-file hunk: {:?}",
        update.items()
    );

    // The file's group starts collapsed, so open it to see the block rows.
    let (_, update) = expand_file_group(&mut ws, PickerKind::GitChanges, "a.rs").await;
    let items = update.items();
    let PickerItem::GitChange {
        relative_path,
        line,
        preview,
        ..
    } = &items[1]
    else {
        panic!("expected a GitChange row, got {:?}", items[1]);
    };
    assert_eq!(relative_path, "a.rs");
    assert_eq!(*line, 0, "the row jumps to the top of the block");
    // The marker line is the preview: unmistakably a conflict, and it names the side.
    assert!(
        preview.starts_with("<<<<<<<"),
        "expected the block's marker line, got {preview:?}"
    );

    drop(server);
}

/// Resolving by hand — editing the markers away — has to take the decoration with it, because the
/// count reaching zero is what tells the user (and mark-resolved) that the file is done. The scan
/// runs on the per-edit path for exactly this.
#[tokio::test]
async fn resolving_by_hand_clears_the_conflict_decoration() {
    let (server, mut ws, _dir, _ours, buffer_id) = setup_stopped_rebase().await;

    // Replace the whole buffer with a resolution: select everything, then type over it.
    let _: CursorState =
        send_request::<CursorSelectAll>(&mut ws, &CursorSelectAllParams { buffer_id }).await;
    let _: EditResult = send_request::<InputText>(
        &mut ws,
        &InputTextParams {
            buffer_id,
            text: "resolved\n".into(),
            select_pasted: false,
            replace_selection: true,
            at: None,
        },
    )
    .await;

    let window = window_of(&mut ws, buffer_id).await;
    assert!(
        window
            .root
            .lines()
            .into_iter()
            .all(|l| l.change.conflict().is_none()),
        "the markers are gone, so the sides are too"
    );
    assert_eq!(
        window.git_status.expect("in a repo").conflicts,
        0,
        "nothing left to resolve — mark-resolved is now the next step"
    );

    drop(server);
}

// -------- cancelling a long-running operation --------------------------------------------------------

/// Install a `post-merge` hook in `ours` running `body`. The portable way to make a pull take long
/// enough to cancel: no network, no timing luck.
fn install_post_merge_hook(ours: &std::path::Path, body: &str) {
    let hooks = ours.join(".git/test-hooks"); // where `isolate_repo_config` points core.hooksPath
    std::fs::create_dir_all(&hooks).unwrap();
    let hook = hooks.join("post-merge");
    std::fs::write(&hook, format!("#!/bin/sh\n{body}\n")).unwrap();
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        std::fs::set_permissions(&hook, std::fs::Permissions::from_mode(0o755)).unwrap();
    }
}

/// **A client can cancel its own in-flight operation.** Not a detail of pull: handlers are
/// dispatched sequentially in line on the reader loop, so before `is_detachable` existed the cancel
/// frame sat unread behind the very operation it was meant to stop — for fetch and push too. The
/// whole `Space g x` feature was inert, and the way it failed (a request that is simply never read)
/// is invisible to any test that sends one request at a time.
#[tokio::test]
async fn a_client_can_cancel_its_own_in_flight_pull() {
    let (_dir, base, ours, url) = repo_with_origin();
    run_git(&ours, &["push", "-u", "origin", "main"]);
    run_git(&ours, &["config", "pull.rebase", "false"]);
    someone_else_pushes(&base, &url, "b.rs");
    // The hook announces itself before sleeping, so the test can wait for the pull to *actually* be
    // running rather than assuming it is by the time the next frame goes out — putting the cancel on
    // the wire first only proved the server was reading, and a cancel that arrived before the
    // operation registered came back `cancelled: false`.
    install_post_merge_hook(
        &ours,
        "touch \"$(git rev-parse --git-dir)/aether-pull-running\"\nsleep 20",
    );

    let (server, mut ws) = setup_repos_workspace(vec![ours.clone()]).await;
    let repo_id: String = ours.to_string_lossy().into();
    let _pull = send_no_wait::<GitPull>(
        &mut ws,
        &GitPullParams {
            repo_id: Some(repo_id.clone()),
            buffer_id: None,
        },
    )
    .await;

    let running = ours.join(".git/aether-pull-running");
    for _ in 0..200 {
        if running.exists() {
            break;
        }
        tokio::time::sleep(std::time::Duration::from_millis(50)).await;
    }
    assert!(running.exists(), "the pull never reached its hook");

    // Answered while the pull is still sleeping in its hook — the assertion is that this returns at
    // all, long before the 20s hook could finish.
    let res: GitCancelResult = tokio::time::timeout(
        std::time::Duration::from_secs(5),
        send_request::<GitCancel>(&mut ws, &GitCancelParams { repo_id }),
    )
    .await
    .expect("git/cancel must be readable while a pull is in flight");
    assert!(res.cancelled, "an operation was running and was stopped");

    drop(server);
}

/// Cancelling SIGKILLs git, and unlike fetch and push a pull's merge half writes the index — so a
/// cancel can strand `.git/index.lock`, which makes *every* later git operation in the repo fail.
///
/// The lock here is **planted by the hook, not raced for**: reproducing a kill inside git's own
/// index write is a coin toss, and what needs pinning is that a cancelled pull *looks* for the lock
/// and reports it rather than saying a bare "cancelled" over a repo that is now wedged.
///
/// The hook announces itself with a separate marker, and the test waits for *that* rather than for
/// `index.lock` itself. Git holds its own `index.lock` for the duration of the merge and releases it
/// by renaming the lock over the index — so waiting on the lock file could match git's transient one,
/// cancel while the merge was still running, and find the path empty a moment later when git had
/// released it and the hook had not yet run. That is what made this test flaky roughly one run in
/// eight.
#[tokio::test]
async fn a_cancelled_pull_reports_a_stranded_index_lock() {
    let (_dir, base, ours, url) = repo_with_origin();
    run_git(&ours, &["push", "-u", "origin", "main"]);
    run_git(&ours, &["config", "pull.rebase", "false"]);
    someone_else_pushes(&base, &url, "b.rs");
    install_post_merge_hook(
        &ours,
        "touch \"$(git rev-parse --git-dir)/index.lock\"\n\
         touch \"$(git rev-parse --git-dir)/aether-hook-ran\"\nsleep 20",
    );

    let (server, mut ws) = setup_repos_workspace(vec![ours.clone()]).await;
    let repo_id: String = ours.to_string_lossy().into();
    let pull = send_no_wait::<GitPull>(
        &mut ws,
        &GitPullParams {
            repo_id: Some(repo_id.clone()),
            buffer_id: None,
        },
    )
    .await;
    // Wait for the hook's own marker, not for `index.lock`: only the marker proves the merge is
    // past its index write and the lock now on disk is the planted one.
    let ran = ours.join(".git/aether-hook-ran");
    for _ in 0..200 {
        if ran.exists() {
            break;
        }
        tokio::time::sleep(std::time::Duration::from_millis(50)).await;
    }
    assert!(ran.exists(), "the post-merge hook never ran");
    assert!(
        ours.join(".git/index.lock").exists(),
        "the hook plants the lock before announcing itself"
    );
    let _: GitCancelResult = send_request::<GitCancel>(&mut ws, &GitCancelParams { repo_id }).await;

    let res: GitPullResult = await_response::<GitPull>(&mut ws, pull).await;
    assert_eq!(res.status, GitPullStatus::Cancelled);
    assert!(
        res.index_locked,
        "a cancelled pull must notice the lock it may have stranded"
    );

    drop(server);
}

// -------- the baseline picker (PickerKind::GitBaseline) ------------------------------------------

use aether_protocol::picker::{GroupHeader, PickerViewResult};

/// The label of the row a baseline-picker view opens highlighting — the server's
/// `effective_center_on`, which is what the client adopts as its selection.
fn opened_on(view: &PickerViewResult) -> Option<&str> {
    match view.effective_center_on.as_ref()? {
        PickerItem::GitBaseline { label, .. } => Some(label.as_str()),
        other => panic!("expected a baseline row, got {other:?}"),
    }
}

/// Two sections — the working states, then the revisions — with the non-revisions bracketed. The
/// order within the list is meaning, not score, so the fixed rows have to survive a query a branch
/// name matches better.
#[tokio::test]
async fn baseline_picker_groups_working_state_and_revisions() {
    let dir = tempfile::tempdir().unwrap();
    let root = dir.path().canonicalize().unwrap();
    let repo = init_repo_at(&root);
    commit_file(&repo, "a.rs", "one\n");
    repo.branch(
        "feature",
        &repo.head().unwrap().peel_to_commit().unwrap(),
        false,
    )
    .unwrap();

    let (server, mut ws, buffer) = setup_repos_workspace_on(vec![root.clone()], "a.rs").await;

    let view =
        send_request::<PickerView>(&mut ws, &view_params_on(PickerKind::GitBaseline, buffer)).await;
    let update = view.update.clone().expect("window");

    // Section headers, in order, at the boundaries the labels' brackets predict.
    let headers: Vec<(u32, String)> = update
        .groups
        .iter()
        .map(|g| match &g.header {
            GroupHeader::Label { label } => (g.start, label.clone()),
            other => panic!("expected a label header, got {other:?}"),
        })
        .collect();
    assert_eq!(
        headers,
        vec![
            (0, "Working state".to_string()),
            (2, "Revisions".to_string())
        ],
        "`(index)`/`(saved)` are one section, `HEAD` and the branches the other"
    );
    assert!(
        update.groups.iter().all(|g| g.count.is_none()),
        "derived, always-expanded headers — not collapsible rows"
    );

    let items = update.items().to_vec();
    let labels: Vec<&str> = items
        .iter()
        .map(|i| match i {
            PickerItem::GitBaseline { label, .. } => label.as_str(),
            other => panic!("expected a baseline row, got {other:?}"),
        })
        .collect();
    assert_eq!(
        &labels[..3],
        &["(index)", "(saved)", "HEAD"],
        "the fixed rows lead, in meaning order, non-revisions bracketed"
    );
    assert!(
        labels[3..].contains(&"feature"),
        "branches follow the fixed rows: {labels:?}"
    );

    // Order is meaning, not score: a query a branch name matches better must not float it above
    // the fixed rows, which are the answers worth one keystroke.
    let _: () = send_request::<PickerQuery>(
        &mut ws,
        &PickerQueryParams {
            kind: PickerKind::GitBaseline,
            query: "e".into(),
            generation: 1,
            filters: Default::default(),
        },
    )
    .await;
    let update: PickerUpdateParams = expect_notification::<PickerUpdate>(&mut ws).await;
    let filtered: Vec<&str> = update
        .items()
        .iter()
        .map(|i| match i {
            PickerItem::GitBaseline { label, .. } => label.as_str(),
            other => panic!("expected a baseline row, got {other:?}"),
        })
        .collect();
    assert_eq!(
        filtered.first(),
        Some(&"(index)"),
        "`(index)` still leads a query `feature` scores higher on: {filtered:?}"
    );
    assert!(filtered.contains(&"feature"), "{filtered:?}");

    // Where you are is the selection, not a glyph: an unpinned repo opens on `(index)`.
    assert_eq!(
        opened_on(&view),
        Some("(index)"),
        "a fresh open highlights the baseline in force"
    );

    drop(server);
}

/// Enter on the `saved` row re-baselines the repo, and the picker then marks that row instead. The
/// round trip is what proves the row's `choice` is the same value the RPC takes.
#[tokio::test]
async fn baseline_picker_row_sets_the_baseline() {
    let dir = tempfile::tempdir().unwrap();
    let root = dir.path().canonicalize().unwrap();
    let repo = init_repo_at(&root);
    commit_file(&repo, "a.rs", "one\n");

    let (server, mut ws, buffer) = setup_repos_workspace_on(vec![root.clone()], "a.rs").await;

    let view =
        send_request::<PickerView>(&mut ws, &view_params_on(PickerKind::GitBaseline, buffer)).await;
    let items = view.update.expect("window").items().to_vec();
    let saved = items
        .iter()
        .find_map(|i| match i {
            PickerItem::GitBaseline {
                repo_id,
                choice,
                label,
                ..
            } if label == "(saved)" => Some((repo_id.clone(), choice.clone())),
            _ => None,
        })
        .expect("a saved row");

    let res: GitSetBaselineResult = send_request::<GitSetBaseline>(
        &mut ws,
        &GitSetBaselineParams {
            repo_id: saved.0,
            source: saved.1,
        },
    )
    .await;
    assert!(matches!(res.baseline, Some(GitBaselineSource::Saved)));

    // Re-opening now lands on `(saved)` — the picker says where you are by highlighting it.
    let view =
        send_request::<PickerView>(&mut ws, &view_params_on(PickerKind::GitBaseline, buffer)).await;
    assert_eq!(opened_on(&view), Some("(saved)"));

    drop(server);
}
